 private static Captured capture0(RootRuntimeContext context,Session same,Optional<OriginalRuntimeHandoffProof.Lease> legacy,Optional<ManagedCapture> managed)throws IOException{
  context.writer().requireSession(same);require(legacy.isPresent()!=managed.isPresent(),"exactly one finite Holy custody origin required");Path store=store(context);if(managed.isPresent())managed.orElseThrow().scope().requireFrame(same,managed.orElseThrow().actual());else{var lease=legacy.orElseThrow();lease.requireCurrent();require(lease.originalStore().equals(store)&&lease.machineId().equals(context.game().machineId()),"actual Holy original store proof required");}
  boolean present=Files.exists(store,LinkOption.NOFOLLOW_LINKS);Path ancestor=store;while(!Files.exists(ancestor,LinkOption.NOFOLLOW_LINKS)){ancestor=ancestor.getParent();require(ancestor!=null&&ancestor.startsWith(context.game().launchPlan().stateDirectory().toAbsolutePath().normalize()),"original Holy store lacks an actual owned existing parent");}SharedSourceFiles.plainAncestors(ancestor);SharedSourceFiles.DirectoryIdentity directoryIdentity=SharedSourceFiles.nativeDirectory(ancestor);List<String> roster=names(store);var pins=new ArrayList<Pin>();var files=StrictJson.object().putArray("files");long total=0;
  for(String name:roster){Path file=store.resolve(name);SharedSourceFiles.plainAncestors(file);require(Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS),"original once member is not a plain file");long length=Files.size(file);require(length>=0&&length<=MAX_FILE,"one original Holy claim exceeds finite capacity");total=Math.addExact(total,length);require(total<=MAX_TOTAL,"complete Holy once census exceeds finite capacity; no truncation");byte[] bytes;try(var in=Files.newInputStream(file)){bytes=in.readNBytes(MAX_FILE+1);}require(bytes.length==length,"original Holy file changed during capture");var source=new ExactRef(file.toString(),length,ActionCodec.sha256(bytes));Pin pin=same.capturePin(source,MAX_FILE);byte[] actual=same.readPinned(pin,MAX_FILE);same.verifyPin(pin);require(Arrays.equals(actual,bytes),"original Holy source identity/content changed");ExactRef preserved=context.archive().preserveArtifact(same,actual,MAX_FILE);require(Arrays.equals(actual,context.archive().readArtifact(same,preserved,MAX_FILE)),"preserved Holy original differs");pins.add(pin);var entry=files.addObject().put("leaf",name);entry.set("original",source.toJson());var identity=pin.identity();entry.putObject("identity").put("volume_serial_decimal",identity.volumeSerialDecimal()).put("file_id_decimal",identity.fileIdDecimal()).put("creation_filetime_decimal",identity.creationFiletimeDecimal()).put("modified_instant",identity.modifiedInstant()).put("bytes",identity.bytes());entry.set("preserved",preserved.toJson());}
  byte[] observed;List<ExactRef> sourceEvidence;Origin origin;if(managed.isPresent()){var current=managed.orElseThrow();observed=current.scope().observe(same,current.actual());sourceEvidence=current.sources();origin=Origin.JAVA_MANAGED;}else{var lease=legacy.orElseThrow();observed=lease.originalObservation();sourceEvidence=lease.originalEvidence();var observation=OriginalRuntimeHandoffObservation.decode(OriginalRuntimeHandoffObservation.Scope.HOLY_CREATION,observed,store,context.game().machineId(),sourceEvidence);require(Path.of(observation.originalStore()).equals(store),"original Holy custody observation scope differs");origin=Origin.ORIGINAL_PYTHON;}String captureHead=same.head().digest();ExactRef originalObservation=context.archive().preserveArtifact(same,observed,MAX_FILE);require(same.head().digest().equals(captureHead),"Holy archive publication crossed its captured canonical predecessor");
  ObjectNode n=StrictJson.object().put("schema",origin==Origin.JAVA_MANAGED?JAVA_SCHEMA:SCHEMA).put("machine_id",context.game().machineId()).put("original_store",store.toString()).put("directory_present",present).put("capture_head_sha256",captureHead);n.putObject("original_directory_identity").put("path",ancestor.toString()).put("volume_serial_decimal",directoryIdentity.volumeSerialDecimal()).put("file_id_decimal",directoryIdentity.fileIdDecimal()).put("creation_filetime_decimal",directoryIdentity.creationFiletimeDecimal());n.set(origin==Origin.JAVA_MANAGED?"java_managed_session_observation":"original_owned_runtime_observation",originalObservation.toJson());var evidence=n.putArray("source_evidence");sourceEvidence.forEach(v->evidence.add(v.toJson()));var complete=n.putArray("complete_relevant_roster");roster.forEach(complete::add);n.set("files",files);ExactRef manifest=context.archive().withSession(same).preserveMaterial(ReligionCodec.raw(n));Captured capture=new Captured(manifest,pins,roster,present,ancestor,directoryIdentity,observed,origin);if(managed.isPresent())capture.requireManagedCurrent(context,same,managed.orElseThrow().scope());else capture.requireCurrent(context,same,legacy.orElseThrow());replay(context,same,manifest,"",false);return capture;
 }
 static void requireUnclaimed(RootRuntimeContext context,Session same,Captured capture,String replayKey)throws IOException{replay(context,same,capture.manifest(),replayKey,true);}
 static void replay(RootRuntimeContext context,Session same,ExactRef reference,String replayKey,boolean rejectClaim)throws IOException{
  context.writer().requireSession(same);var archive=context.archive().withSession(same);ObjectNode n=manifest(archive.loadMaterial(reference));boolean managed=JAVA_SCHEMA.equals(StrictJson.text(n.get("schema")));
  require((managed||n.path("schema").asText().equals(SCHEMA))&&n.path("machine_id").asText().equals(context.game().machineId())&&Path.of(StrictJson.text(n.get("original_store"))).equals(store(context))&&n.path("directory_present").isBoolean(),"retained actual Holy manifest differs");ObjectNode directory=StrictJson.object(n.get("original_directory_identity"),java.util.Set.of("path","volume_serial_decimal","file_id_decimal","creation_filetime_decimal"));Path ancestor=Path.of(StrictJson.text(directory.get("path")));require(ancestor.isAbsolute()&&ancestor.normalize().equals(ancestor)&&store(context).startsWith(ancestor)&&ancestor.startsWith(context.game().launchPlan().stateDirectory().toAbsolutePath().normalize()),"original Holy directory identity escaped actual store owner");new SharedSourceFiles.DirectoryIdentity(StrictJson.text(directory.get("volume_serial_decimal")),StrictJson.text(directory.get("file_id_decimal")),StrictJson.text(directory.get("creation_filetime_decimal")));var evidence=new ArrayList<ExactRef>();require(n.get("source_evidence").isArray(),"retained original source closure missing");for(JsonNode source:n.get("source_evidence"))evidence.add(ExactRef.fromJson(source));if(!managed)OriginalRuntimeHandoffObservation.decode(OriginalRuntimeHandoffObservation.Scope.HOLY_CREATION,context.archive().readArtifact(same,ExactRef.fromJson(n.get("original_owned_runtime_observation")),MAX_FILE),store(context),context.game().machineId(),evidence);else context.archive().readArtifact(same,ExactRef.fromJson(n.get("java_managed_session_observation")),RootManagedSessionScope.MAX_BYTES);
  var names=new ArrayList<String>();require(n.get("files").isArray()&&n.get("files").size()<=512,"bounded full preserved Holy original roster required");long total=0;for(JsonNode value:n.get("files")){ObjectNode file=StrictJson.object(value,java.util.Set.of("leaf","original","identity","preserved"));String leaf=StrictJson.text(file.get("leaf"));require(validLeaf(leaf),"invalid preserved Holy original leaf");ExactRef original=ExactRef.fromJson(file.get("original")),preserved=ExactRef.fromJson(file.get("preserved"));require(Path.of(original.path()).equals(store(context).resolve(leaf))&&original.bytes()<=MAX_FILE,"retained original Holy pathname differs");ObjectNode identity=StrictJson.object(file.get("identity"),java.util.Set.of("volume_serial_decimal","file_id_decimal","creation_filetime_decimal","modified_instant","bytes"));var retainedIdentity=new org.xar.ck3.control.continuity.writer.WriterContracts.FileIdentity(StrictJson.text(identity.get("volume_serial_decimal")),StrictJson.text(identity.get("file_id_decimal")),StrictJson.text(identity.get("creation_filetime_decimal")),StrictJson.text(identity.get("modified_instant")),StrictJson.integer(identity.get("bytes"),0,9007199254740991L));require(retainedIdentity.bytes()==original.bytes(),"original Holy native file identity size differs");byte[] packet=context.archive().readArtifact(same,preserved,MAX_FILE);total=Math.addExact(total,packet.length);require(total<=MAX_TOTAL&&packet.length==original.bytes()&&ActionCodec.sha256(packet).equals(original.sha256()),"actual original Holy packet changed");names.add(leaf);}
  require(names.equals(names.stream().sorted().distinct().toList()),"original Holy closure order/duplicates differ");var declared=new ArrayList<String>();require(n.get("complete_relevant_roster").isArray(),"full original roster missing");n.get("complete_relevant_roster").forEach(v->declared.add(StrictJson.text(v)));require(names.equals(declared)&&(!n.get("directory_present").booleanValue()?names.isEmpty():true)&&n.path("capture_head_sha256").asText().matches("[0-9a-f]{64}"),"retained Holy manifest omits original members or capture head");if(rejectClaim)require(!containsOriginalPending(names,replayKey),"identical original Holy intent is consumed/UNKNOWN; never replay or expire it");
 }
 static void requireManagedCommand(RootRuntimeContext context,Session same,Captured captured,ActionCommand command,RootManagedSessionScope scope,List<ExactRef> sources)throws IOException{captured.requireManagedCurrent(context,same,scope);ObjectNode census=manifest(context.archive().withSession(same).loadMaterial(captured.manifest()));byte[] bound=RootManagedSessionScope.bindCommand(captured.observation(),command,sources);requireManagedBinding(census,captured.observation(),bound,command,sources);scope.verifyArchived(bound,command,sources,StrictJson.text(census.get("capture_head_sha256")));captured.requireManagedCurrent(context,same,scope);}
 static NativeRequest bindPreparation(RootRuntimeContext context,Session same,Captured captured,ActionCommand command,NativeRequest original,RootManagedSessionScope scope,List<ExactRef> sources)throws IOException{
  context.writer().requireSession(same);require(original.preparationEvidence().isEmpty(),"Holy original registration added preparation roles that need an explicit migration");replay(context,same,captured.manifest(),onceKey(command),true);if(captured.origin()==Origin.ORIGINAL_PYTHON)return new NativeRequest(original.step(),original.requiredCapability(),original.additionalFields(),List.of(captured.manifest()));
  captured.requireManagedCurrent(context,same,scope);ObjectNode census=manifest(context.archive().withSession(same).loadMaterial(captured.manifest()));byte[] frame=context.archive().readArtifact(same,ExactRef.fromJson(census.get("java_managed_session_observation")),RootManagedSessionScope.MAX_BYTES);require(Arrays.equals(frame,captured.observation()),"Holy original Java frame evidence differs from its live capture");byte[] bound=RootManagedSessionScope.bindCommand(frame,command,sources);ExactRef commandOriginal=context.archive().withSession(same).preserveMaterial(new RawJson(bound));require(Arrays.equals(bound,context.archive().withSession(same).loadMaterial(commandOriginal).bytes()),"Holy command-bound Java original readback differs");requireManagedBinding(census,frame,bound,command,sources);scope.verifyArchived(bound,command,sources,StrictJson.text(census.get("capture_head_sha256")));captured.requireManagedCurrent(context,same,scope);return new NativeRequest(original.step(),original.requiredCapability(),original.additionalFields(),List.of(captured.manifest(),commandOriginal));
 }
 static void verifyPreparation(RootRuntimeContext context,Session same,ExactRef reference,String key,ActionCommand command,Optional<NativeRequest> prepared,ActionPorts.OutcomeArchive archive,List<ExactRef> sources)throws IOException{
  context.writer().requireSession(same);replay(context,same,reference,key,true);ObjectNode census=manifest(archive.loadMaterial(reference));if(SCHEMA.equals(StrictJson.text(census.get("schema")))){prepared.ifPresent(v->require(v.preparationEvidence().isEmpty()||v.preparationEvidence().equals(List.of(reference)),"legacy Holy preparation original roles differ"));return;}
  byte[] frame=context.archive().readArtifact(same,ExactRef.fromJson(census.get("java_managed_session_observation")),RootManagedSessionScope.MAX_BYTES),bound;if(prepared.isPresent()){List<ExactRef> refs=prepared.orElseThrow().preparationEvidence();require(refs.size()==2&&refs.getFirst().equals(reference),"Java Holy native preparation must retain its exact census and command-bound original");bound=archive.loadMaterial(refs.get(1)).bytes();}else{bound=RootManagedSessionScope.bindCommand(frame,command,sources);}
  requireManagedBinding(census,frame,bound,command,sources);RootManagedSessionScope.verifyArchived(context.core(),same,bound,command,sources,StrictJson.text(census.get("capture_head_sha256")));
 }
 /** Pure DATA validation shared by actual archived consumers and software producer/serde regressions. It issues no scope. */
 static RootManagedSessionScope.Observation requireManagedBinding(ObjectNode census,byte[] originalFrame,byte[] originalBound,ActionCommand command,List<ExactRef> sources){
  require(JAVA_SCHEMA.equals(StrictJson.text(census.get("schema"))),"original Python observation cannot be relabeled as a Java Holy source");var declared=new ArrayList<ExactRef>();require(census.get("source_evidence").isArray(),"complete Holy Java source evidence required");census.get("source_evidence").forEach(v->declared.add(ExactRef.fromJson(v)));require(declared.equals(sources),"Holy Java original source closure differs");require(Arrays.equals(RootManagedSessionScope.bindCommand(originalFrame,command,sources),originalBound),"Holy command-bound original differs from its actual frame and complete command body");var observed=RootManagedSessionScope.decode(originalBound,command,sources);require(observed.actionBodySha256().equals(Optional.of(ActionCodec.bodySha256(command)))&&observed.headDigest().equals(StrictJson.text(census.get("capture_head_sha256"))),"Holy Java archive crossed its original command/predecessor");return observed;
 }
 private static ObjectNode manifest(RawJson original){JsonNode value=StrictJson.parse(original.bytes());String schema=StrictJson.text(value.get("schema"));require(schema.equals(SCHEMA)||schema.equals(JAVA_SCHEMA),"finite Holy once-census version required");return StrictJson.object(value,java.util.Set.of("schema","machine_id","original_store","directory_present","capture_head_sha256","original_directory_identity",schema.equals(JAVA_SCHEMA)?"java_managed_session_observation":"original_owned_runtime_observation","source_evidence","complete_relevant_roster","files"));}
 private static String onceKey(ActionCommand command){JsonNode meta=org.xar.ck3.control.planning.opportunity.OpportunityJson.toNode(command.arguments()).get(RootReligionHolyPublicProducts.META);String key=StrictJson.text(meta.get("once_key"));require(key.matches("[0-9a-f]{64}"),"Holy actual semantic once key required");return key;}
 private static boolean validLeaf(String leaf){return leaf.matches("[0-9a-f]{64}\\.pending\\.json")||leaf.matches("[0-9a-f]{64}\\.creation-create-[0-9a-f]{32}\\.result\\.json");}
 static boolean containsOriginalPending(List<String> completeRoster,String key){require(key.matches("[0-9a-f]{64}"),"actual original Holy once key required");return completeRoster.contains(key+".pending.json");}
 static List<String> names(Path folder)throws IOException{if(!Files.exists(folder,LinkOption.NOFOLLOW_LINKS))return List.of();SharedSourceFiles.plainAncestors(folder);require(Files.isDirectory(folder,LinkOption.NOFOLLOW_LINKS),"actual original Holy store is not plain directory");var names=new ArrayList<String>();int scanned=0;try(var stream=Files.newDirectoryStream(folder)){for(Path p:stream){require(++scanned<=8192,"complete Holy directory enumeration exceeds finite capacity");String leaf=p.getFileName().toString();String folded=leaf.toLowerCase(java.util.Locale.ROOT);if(folded.endsWith(".pending.json")||folded.endsWith(".result.json")){require(leaf.equals(folded)&&validLeaf(leaf),"malformed original Holy once pathname retained as unavailable");require(names.size()<512,"full Holy original claim/result bound exceeded; no truncation");names.add(leaf);}}}names.sort(Comparator.naturalOrder());return List.copyOf(names);}
